const updateMediaFileParsed = `-- name: UpdateMediaFileParsed :exec
UPDATE media_files
SET parsed = ?,
    match_error  = CASE WHEN match_locked = 0 AND match_status IN ('unmatched', 'failed') THEN NULL ELSE match_error END,
    match_status = CASE WHEN match_locked = 0 AND match_status IN ('unmatched', 'failed') THEN 'pending' ELSE match_status END,
    updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
WHERE id = ?
`

type UpdateMediaFileParsedParams struct {
	Parsed string `json:"parsed"`
	ID     int64  `json:"id"`
}

// A file whose name now reads differently (the parser learned something):
// store the new reading, and send it back to matching unless it is matched
// or a person chose its match.
func (q *Queries) UpdateMediaFileParsed(ctx context.Context, arg UpdateMediaFileParsedParams) error {
	_, err := q.db.ExecContext(ctx, updateMediaFileParsed, arg.Parsed, arg.ID)
	return err
}

const upsertMediaFile = `-- name: UpsertMediaFile :one
INSERT INTO media_files (
    library_id, path, size, mtime, status, parsed, probe, probe_error,
    container, video_codec, audio_codec, width, height, duration_ms, last_seen_at, seen_in_scan, hdr, added_at, dv_profile, extra_kind
)
VALUES (?, ?, ?, ?, 'present', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
ON CONFLICT (path) DO UPDATE SET
    library_id   = excluded.library_id,
    size         = excluded.size,
    mtime        = excluded.mtime,
    status       = 'present',
    parsed       = excluded.parsed,
    probe        = excluded.probe,
    probe_error  = excluded.probe_error,
    container    = excluded.container,
    video_codec  = excluded.video_codec,
    audio_codec  = excluded.audio_codec,
    width        = excluded.width,
    height       = excluded.height,
    duration_ms  = excluded.duration_ms,
    last_seen_at = excluded.last_seen_at,
    seen_in_scan = excluded.seen_in_scan,
    hdr          = excluded.hdr,
    dv_profile   = excluded.dv_profile,
    extra_kind   = excluded.extra_kind,
    updated_at   = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
RETURNING id, library_id, path, size, mtime, status, parsed, probe, probe_error, container, video_codec, audio_codec, width, height, duration_ms, first_seen_at, last_seen_at, seen_in_scan, created_at, updated_at, movie_id, match_status, match_locked, match_candidates, match_error, matched_at, hdr, added_at, match_ignored, dv_profile, extra_kind, extra_of
`

type UpsertMediaFileParams struct {
	LibraryID  int64   `json:"library_id"`
	Path       string  `json:"path"`
	Size       int64   `json:"size"`
	Mtime      string  `json:"mtime"`
	Parsed     string  `json:"parsed"`
	Probe      *string `json:"probe"`
	ProbeError *string `json:"probe_error"`
	Container  *string `json:"container"`
	VideoCodec *string `json:"video_codec"`
	AudioCodec *string `json:"audio_codec"`
	Width      *int64  `json:"width"`
	Height     *int64  `json:"height"`
	DurationMs *int64  `json:"duration_ms"`
	LastSeenAt string  `json:"last_seen_at"`
	SeenInScan int64   `json:"seen_in_scan"`
	Hdr        string  `json:"hdr"`
	AddedAt    string  `json:"added_at"`
	DvProfile  *int64  `json:"dv_profile"`
	ExtraKind  *string `json:"extra_kind"`
}

// added_at is kept: a file that changes on disk keeps its place in Recently
// added. A change of extra_kind is the scanner's to finish (SetMediaFileExtra).
func (q *Queries) UpsertMediaFile(ctx context.Context, arg UpsertMediaFileParams) (MediaFile, error) {
	row := q.db.QueryRowContext(ctx, upsertMediaFile,
		arg.LibraryID,
		arg.Path,
		arg.Size,
		arg.Mtime,
		arg.Parsed,
		arg.Probe,
		arg.ProbeError,
		arg.Container,
		arg.VideoCodec,
		arg.AudioCodec,
		arg.Width,
		arg.Height,
		arg.DurationMs,
		arg.LastSeenAt,
		arg.SeenInScan,
		arg.Hdr,
		arg.AddedAt,
		arg.DvProfile,
		arg.ExtraKind,
	)
	var i MediaFile
	err := row.Scan(
		&i.ID,
		&i.LibraryID,
		&i.Path,
		&i.Size,
		&i.Mtime,
		&i.Status,
		&i.Parsed,
		&i.Probe,
		&i.ProbeError,
		&i.Container,
		&i.VideoCodec,
		&i.AudioCodec,
		&i.Width,
		&i.Height,
		&i.DurationMs,
		&i.FirstSeenAt,
		&i.LastSeenAt,
		&i.SeenInScan,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.MovieID,
		&i.MatchStatus,
		&i.MatchLocked,
		&i.MatchCandidates,
		&i.MatchError,
		&i.MatchedAt,
		&i.Hdr,
		&i.AddedAt,
		&i.MatchIgnored,
		&i.DvProfile,
		&i.ExtraKind,
		&i.ExtraOf,
	)
	return i, err
}
